from copy import deepcopy


class CommandInbox:
    def __init__(self, users):
        if isinstance(users, (str, bytes)):
            raise TypeError("users must be an iterable of user IDs")
        try:
            values = list(users)
        except TypeError as exc:
            raise TypeError("users must be iterable") from exc
        if any(not isinstance(user, str) or not user for user in values):
            raise ValueError("user IDs must be non-empty strings")
        self._users = set(values)
        self._stored = []
        self._audit = []

    def submit(self, user_id, request):
        if user_id not in self._users:
            raise PermissionError("unknown user")
        if not isinstance(request, dict):
            raise TypeError("request must be a dictionary")
        if set(request) != {"action", "payload"}:
            raise ValueError("request must contain exactly action and payload")
        action = request["action"]
        if action not in {"store", "echo"}:
            raise ValueError("unknown action")
        request_copy = request
        if action == "store":
            self._stored.append(deepcopy(request_copy["payload"]))
        self._audit.append({"user_id": user_id, "request": request_copy})
        return {"ok": True, "result": deepcopy(request_copy["payload"])}

    def stored(self):
        return deepcopy(self._stored)

    def audit(self):
        return deepcopy(self._audit)

